import java.io.*;import java.util.*;import java.awt.image.*;import com.koios.client.arpg.*;import com.koios.client.graphic.*;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;
/** Staged new currencies remain important loot and fail gracefully when illustration files are unavailable. */
public final class CurrencyLabelAuditCheck {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static void main(String[]args)throws Exception{int[] ids={22407,22408,22409,22415,22416};if(args.length>0){Set<Integer> hashes=new HashSet<>();for(int id:ids){Sprite s=CurrencyIcons.sprite(id);check(s!=null&&s.myWidth==32&&s.myHeight==32,"Missing atlas has usable fallback "+id);int count=0;for(int p:s.myPixels)if(p!=0)count++;check(count>100,"Fallback silhouette visible");check(s==CurrencyIcons.sprite(id),"Repeated missing-art request reuses bounded fallback cache");check(hashes.add(Arrays.hashCode(s.myPixels)),"Fallback remains distinct per currency");}System.out.println("Passed "+checks+" missing-atlas bounded fallback checks.");return;}
 try(RandomAccessFile data=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile index=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(data,index,1).decompress(1)));GroundLootLabels labels=new GroundLootLabels();for(int id:ids){String name=CurrencyIcons.name(id);labels.accept("add|currency"+id+"|100|100|0|"+id+"||14013909|1|"+Base64.getEncoder().encodeToString(name.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}int[] px=new int[512*334];DrawingArea.initDrawingArea(334,512,px);labels.draw(font,(x,y,h)->new int[]{256,260},0,100,100,false,-1,-1);check(labels.visibleCount()==5,"All five new orbs display without Alt as important nearby loot");Set<Integer> hit=new HashSet<>();for(int y=0;y<334;y++)for(int x=0;x<512;x++){GroundLootLabels.Entry e=labels.hit(x,y);if(e!=null)hit.add(e.id);}for(int id:ids)check(hit.contains(id),"Actual hit plate resolves exact new currency "+id);labels.draw(font,(x,y,h)->new int[]{256,260},0,107,100,false,-1,-1);check(labels.visibleCount()==0,"Default important-loot range limit retained");labels.draw(font,(x,y,h)->new int[]{256,260},0,107,100,true,-1,-1);check(labels.visibleCount()==5,"Alt expands range to new currencies");}System.out.println("Passed "+checks+" staged new currency important-label checks.");}
}
